-- V19: 应聘者小程序公司动态

CREATE TABLE IF NOT EXISTS `mini_news`
(
    `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增编号',
    `title`         VARCHAR(200) NOT NULL COMMENT '标题',
    `summary`       VARCHAR(500) DEFAULT NULL COMMENT '摘要',
    `content`       MEDIUMTEXT NOT NULL COMMENT '正文',
    `publish_date`  DATE NOT NULL COMMENT '发布日期',
    `created_by`    INT DEFAULT NULL COMMENT '创建人',
    `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updated_by`    INT DEFAULT NULL COMMENT '最后修改人',
    `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
    `deleted`       TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除：0未删 1已删',
    PRIMARY KEY (`id`),
    KEY `idx_mini_news_date` (`publish_date`, `deleted`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公司动态';

-- 插入15条测试数据
INSERT INTO `mini_news` (title, summary, content, publish_date) VALUES
('北海创享人才中心第四期新学员开班仪式顺利举行', '求知无坦途，学问无捷径。2022年3月16日，北海创享人才中心第四期新学员开班仪式在中心……', '求知无坦途，学问无捷径。2022年3月16日，北海创享人才中心第四期新学员开班仪式在中心报告厅隆重举行。本次开班共有来自全省各地的80余名新学员参加，涵盖Java开发、前端开发、软件测试等多个方向。开班仪式上，总经理发表了热情洋溢的讲话，鼓励新学员珍惜学习机会，努力提升专业技能，为未来的职业发展打下坚实基础。', '2022-04-01'),
('北海软件荣获ISO27001信息安全管理体系认证', '近日，济南北海软件工程有限公司顺利通过ISO27001信息安全管理体系认证，标志着公司在信息安全管理领域达到了国际……', '近日，济南北海软件工程有限公司顺利通过ISO27001信息安全管理体系认证，标志着公司在信息安全管理领域达到了国际标准化水平。该认证的获得，是公司对客户信息安全承诺的重要体现，也为公司开拓对日软件外包业务提供了有力保障。', '2022-05-15'),
('北海软件与国家电网签订年度服务合同', '经过多轮技术交流和商务谈判，北海软件正式与国家电网山东分公司签订年度软件技术服务合同，为其提供定制……', '经过多轮技术交流和商务谈判，北海软件正式与国家电网山东分公司签订年度软件技术服务合同，为其提供定制化软件开发与运维服务。这是公司与国家电网首次建立年度合作关系，标志着公司在电力行业信息化领域的服务能力得到了客户认可。', '2022-06-20'),
('公司组织2022年夏季团建活动', '为丰富员工文化生活，增强团队凝聚力，公司于7月组织全体员工前往泰山开展为期两天的夏季团建活动……', '为丰富员工文化生活，增强团队凝聚力，公司于7月组织全体员工前往泰山开展为期两天的夏季团建活动。活动包括登山比赛、团队拓展训练、篝火晚会等环节，大家在放松身心的同时也加深了同事之间的友谊。', '2022-07-10'),
('北海软件参加第十届中国国际软件博览会', '2022年8月，第十届中国国际软件博览会在济南国际会展中心举行，北海软件作为参展企业，展示了公司在对日……', '2022年8月，第十届中国国际软件博览会在济南国际会展中心举行，北海软件作为参展企业，展示了公司在对日软件外包、企业数字化转型等领域的最新成果。展会期间，公司接待了来自全国各地的客户代表200余人次，达成合作意向12项。', '2022-08-05'),
('公司党支部组织学习党的二十大精神', '为深入学习贯彻党的二十大精神，公司党支部于10月组织全体党员和入党积极分子开展专题学习活动……', '为深入学习贯彻党的二十大精神，公司党支部于10月组织全体党员和入党积极分子开展专题学习活动。大家集体观看了开幕会实况录像，并围绕报告内容进行了热烈讨论。党员们纷纷表示，要将学习成果转化为工作动力，立足岗位做出更大贡献。', '2022-10-25'),
('北海软件获评"山东省高新技术企业"', '经过严格的评审和公示，北海软件正式通过2022年高新技术企业认定，这是公司连续第三次获此殊荣……', '经过严格的评审和公示，北海软件正式通过2022年高新技术企业认定，这是公司连续第三次获此殊荣。高新技术企业认定的通过，是对公司在研发投入、技术创新、成果转化等方面综合实力的肯定，也为公司享受税收优惠政策提供了依据。', '2022-11-18'),
('公司举办2023年新春年会', '2023年1月15日，北海软件2023年新春年会在济南喜来登酒店隆重举行，全体员工欢聚一堂，共迎新春……', '2023年1月15日，北海软件2023年新春年会在济南喜来登酒店隆重举行，全体员工欢聚一堂，共迎新春。年会上，总经理回顾了2022年公司取得的成绩，对2023年进行了展望。现场还举行了优秀员工表彰和抽奖活动，气氛热烈。', '2023-01-15'),
('北海软件日本东京分支机构正式开业', '经过半年多的筹备，北海软件东京分支于2023年3月正式开业，标志着公司对日软件外包业务进入新的发展阶段……', '经过半年多的筹备，北海软件东京分支于2023年3月正式开业，标志着公司对日软件外包业务进入新的发展阶段。东京分支将主要负责日本市场的客户拓展和项目管理，为日本客户提供更及时的技术支持服务。', '2023-03-20'),
('公司与浪潮集团建立战略合作关系', '2023年4月，北海软件与浪潮集团正式签署战略合作协议，双方将在企业数字化转型、云计算、大数据等领域……', '2023年4月，北海软件与浪潮集团正式签署战略合作协议，双方将在企业数字化转型、云计算、大数据等领域开展深度合作。根据协议，北海软件将作为浪潮生态合作伙伴，参与多个行业的信息化建设项目。', '2023-04-10'),
('北海软件参加2023届高校毕业生双选会', '2023年5月，北海软件参加了在山东大学举办的高校毕业生双选会，现场提供Java开发、前端开发、软件测试……', '2023年5月，北海软件参加了在山东大学举办的高校毕业生双选会，现场提供Java开发、前端开发、软件测试等多个岗位，收到简历300余份。公司人力资源部门表示，今年校招规模比去年扩大了50%。', '2023-05-20'),
('公司通过CMMI5级软件能力成熟度认证', '经过三个月的评估审核，北海软件正式通过CMMI5级软件能力成熟度模型集成认证，这是目前软件行业的最高等级……', '经过三个月的评估审核，北海软件正式通过CMMI5级软件能力成熟度模型集成认证，这是目前软件行业的最高等级认证。CMMI5级的通过，标志着公司在软件过程管理、质量保证、项目管理等方面达到了国际领先水平。', '2023-06-28'),
('北海软件举办第一届技术分享大会', '2023年7月，公司举办第一届技术分享大会，共有来自各项目组的12位技术骨干上台分享，内容涵盖……', '2023年7月，公司举办第一届技术分享大会，共有来自各项目组的12位技术骨干上台分享，内容涵盖微服务架构、性能优化、AI应用等热门技术话题。大会采用线上线下结合的方式，共300余人参加。', '2023-07-15'),
('公司组织员工体检与健康讲座', '为关爱员工身体健康，公司于8月组织全体员工进行年度体检，并邀请济南市中心医院专家来公司做健康讲座……', '为关爱员工身体健康，公司于8月组织全体员工进行年度体检，并邀请济南市中心医院专家来公司做健康讲座。讲座内容包括职场常见疾病预防、心理健康调适等，受到员工一致好评。', '2023-08-08'),
('北海软件成立十三周年庆典', '2023年10月，北海软件迎来成立十三周年。公司举办了系列庆祝活动，回顾十三年发展历程，展望未来……', '2023年10月，北海软件迎来成立十三周年。公司举办了系列庆祝活动，回顾十三年发展历程，展望未来发展蓝图。总经理在庆典上表示，公司将继续坚持技术创新，为客户提供更优质的软件服务，为员工创造更好的发展平台。', '2023-10-10');
